package io.artio.inventory;
import io.artio.kernel.Aggregate; import io.artio.kernel.Quantity; import java.math.BigDecimal; import java.time.Instant; import java.util.Objects; import java.util.UUID;
/** Order stock commitment with a single legal transition out of RESERVED. */
public final class Reservation extends Aggregate<ReservationId> {
    private final UUID orderId; private final WarehouseId warehouseId; private final UUID sellableId; private final BigDecimal quantity; private BigDecimal allocatedQuantity; private BigDecimal releasedQuantity; private Instant expiresAt; private ReservationState state;
    private Reservation(ReservationId id,UUID orderId,WarehouseId warehouseId,UUID sellableId,BigDecimal quantity,BigDecimal allocatedQuantity,BigDecimal releasedQuantity,Instant expiresAt,ReservationState state){super(id);this.orderId=Objects.requireNonNull(orderId);this.warehouseId=Objects.requireNonNull(warehouseId);this.sellableId=Objects.requireNonNull(sellableId);this.quantity=Objects.requireNonNull(quantity);if(quantity.signum()<=0||quantity.stripTrailingZeros().scale()>4||quantity.precision()>15)throw new IllegalArgumentException("Reservation quantity must be positive, with at most 15 digits and 4 decimal places");this.allocatedQuantity=boundedMovement(allocatedQuantity,quantity);this.releasedQuantity=boundedMovement(releasedQuantity,quantity);if(this.allocatedQuantity.add(this.releasedQuantity).compareTo(quantity)>0)throw new IllegalArgumentException("Allocated and released quantities cannot exceed reservation quantity");this.expiresAt=Objects.requireNonNull(expiresAt,"Reservation expiry is required");this.state=Objects.requireNonNull(state);}
    public static Reservation reserve(ReservationId id,UUID orderId,WarehouseId warehouseId,UUID sellableId,Quantity quantity){return reserve(id,orderId,warehouseId,sellableId,quantity,Instant.now().plusSeconds(1800));}
    public static Reservation reserve(ReservationId id,UUID orderId,WarehouseId warehouseId,UUID sellableId,Quantity quantity,Instant expiresAt){var reservation=new Reservation(id,orderId,warehouseId,sellableId,quantity.value(),BigDecimal.ZERO,BigDecimal.ZERO,expiresAt,ReservationState.RESERVED);reservation.recordEvent(new ReservationCreated(id,orderId,warehouseId,sellableId,quantity.value()));return reservation;}
    public static Reservation reconstitute(ReservationId id,UUID orderId,WarehouseId warehouseId,UUID sellableId,BigDecimal quantity,ReservationState state){return reconstitute(id,orderId,warehouseId,sellableId,quantity,legacyAllocated(quantity,state),legacyReleased(quantity,state),Instant.now().plusSeconds(1800),state);}
    public static Reservation reconstitute(ReservationId id,UUID orderId,WarehouseId warehouseId,UUID sellableId,BigDecimal quantity,Instant expiresAt,ReservationState state){return reconstitute(id,orderId,warehouseId,sellableId,quantity,legacyAllocated(quantity,state),legacyReleased(quantity,state),expiresAt,state);}
    public static Reservation reconstitute(ReservationId id,UUID orderId,WarehouseId warehouseId,UUID sellableId,BigDecimal quantity,BigDecimal allocatedQuantity,BigDecimal releasedQuantity,Instant expiresAt,ReservationState state){return new Reservation(id,orderId,warehouseId,sellableId,quantity,allocatedQuantity,releasedQuantity,expiresAt,state);}
    public void allocate(){if(remainingQuantity().signum()==0)throw new IllegalStateException("No reserved quantity remains to allocate");allocate(remainingQuantity());}
    public void allocate(BigDecimal amount){if(remainingQuantity().signum()==0)throw new IllegalStateException("No reserved quantity remains to allocate");BigDecimal value=movement(amount);if(value.compareTo(remainingQuantity())>0)throw new IllegalStateException("Cannot allocate more stock than remains reserved");allocatedQuantity=allocatedQuantity.add(value);finishIfEmpty();recordEvent(new ReservationStateChanged(getId(),state));}
    public void release(){if(remainingQuantity().signum()==0)throw new IllegalStateException("No reserved quantity remains to release");release(remainingQuantity());}
    public void release(BigDecimal amount){if(remainingQuantity().signum()==0)throw new IllegalStateException("No reserved quantity remains to release");BigDecimal value=movement(amount);if(value.compareTo(remainingQuantity())>0)throw new IllegalStateException("Cannot release more stock than remains reserved");releasedQuantity=releasedQuantity.add(value);finishIfEmpty();recordEvent(new ReservationStateChanged(getId(),state));}
    public void extendExpiry(Instant expiry){if(state!=ReservationState.RESERVED)throw new IllegalStateException("Only a reserved stock commitment can be extended");if(expiry==null||!expiry.isAfter(expiresAt))throw new IllegalArgumentException("Reservation expiry can only be extended");expiresAt=expiry;}
    private void finishIfEmpty(){state=remainingQuantity().signum()==0?(allocatedQuantity.signum()>0?ReservationState.ALLOCATED:ReservationState.RELEASED):ReservationState.RESERVED;}
    private static BigDecimal boundedMovement(BigDecimal value,BigDecimal total){Objects.requireNonNull(value);if(value.signum()<0||value.stripTrailingZeros().scale()>4||value.precision()>15||value.compareTo(total)>0)throw new IllegalArgumentException("Reservation movement is outside its quantity bounds");return value;}
    private static BigDecimal legacyAllocated(BigDecimal quantity,ReservationState state){return state==ReservationState.ALLOCATED?quantity:BigDecimal.ZERO;}
    private static BigDecimal legacyReleased(BigDecimal quantity,ReservationState state){return state==ReservationState.RELEASED?quantity:BigDecimal.ZERO;}
    private BigDecimal movement(BigDecimal amount){Objects.requireNonNull(amount);if(amount.signum()<=0||amount.stripTrailingZeros().scale()>4||amount.precision()>15)throw new IllegalArgumentException("Reservation movement must be positive with at most 15 digits and 4 decimal places");return amount;}
    public UUID getOrderId(){return orderId;} public WarehouseId getWarehouseId(){return warehouseId;} public UUID getSellableId(){return sellableId;} public BigDecimal getQuantity(){return quantity;} public BigDecimal getAllocatedQuantity(){return allocatedQuantity;} public BigDecimal getReleasedQuantity(){return releasedQuantity;} public BigDecimal remainingQuantity(){return quantity.subtract(allocatedQuantity).subtract(releasedQuantity);} public Instant getExpiresAt(){return expiresAt;} public ReservationState getState(){return state;}
}
